"""Checkpoint four checked original CPU helpers and their connected pipeline."""
from datetime import datetime,timezone
import json,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text())
def save(p,x):p.write_text(json.dumps(x,indent=2)+'\n')

def main():
    now=datetime.now(timezone.utc).isoformat();s=Path(read(ROOT/'projects/black-ice-white-noise/analysis/current-session.json')['directory'])
    names=['biwn-text-checks.json','biwn-sprite-checks.json','biwn-inventory-pipeline-checks.json','biwn-inventory-pipeline-runtime-review.json','biwn-pipeline-local-review.json'];text,sprite,pipeline,runtime,local=[read(ROOT/'verification'/n)for n in names]
    assert text['alignment_CPU_cases']==1367 and text['text_CPU_cases']==637 and sprite['CPU_cases']==256 and pipeline['CPU_cases']==54
    assert runtime['groups_compared']==9 and runtime['drawing_and_text_word_records']==5812 and local['status']=='coordinator_reviewed_drafts_rejected_on_numeric_return_and_poll_semantics'
    validation=read(s/'boot-slice-validation.json');assert validation['portable_C_component_count']==17
    validation.update(portable_C_component_count=21,latest_aggregate_update=now,
        component_count_scope='17earlier components plus14776alignment,147A6format3text,149AEtext andE2B8spriteCPUmailbox. Linked pipeline is integration, not an additional originalcomponent. GPUprocessing/drawingrasterization not reconstructed.',
        nextstage_text_CPU_helpers_C=text,nextstage_sprite_CPU_mailbox_C=sprite,nextstage_connected_inventory_CPU_pipeline=pipeline)
    save(s/'boot-slice-validation.json',validation);subprocess.run([str(ROOT/'.venv/bin/python'),str(ROOT/'scripts/summarize_biwn_checks.py')],check=True)
    game='21 isolated portable C components checked. New alignment/text/sprite CPU helpers pass 1,367 alignment cases, 637 text cases and 256 sprite command cases, with 37 host guards. Text includes all three format paths. Connected inventory/text/sprite CPU pipeline passes 54 cases and 13 additional host guards without sprite/text RTS stubs. GPU sprite processing and drawing rasterization remain external; complete rebuilt game unfinished.'
    observed='Nine retained original-game inventory intervals match all 5,812 drawing/text word writes, including 3,112 nested text writes. Uses stable postframe slot snapshots and preserved assets, not instruction-time read capture. GPU mailbox schedules checked separately in CPU fixtures. No rebuilt pixel/frame or hardware equivalence.'
    frontend='Game Assistant compact inventory_drawing evidence topic includes exact CPU examples. Only Game Assistant preset changed; all other presets unchanged. Native Chat adoption unverified while Mac locked; API/local-role logs saved for post review.'
    next_work='Reconstruct GPU4B00processing and drawing rasterization, then test a rebuilt inventory frame and broader game integration. Verify refreshed nativeChat when accessible. Continue advertising semantic/source/teaching evaluation before further training or default promotion. Full goal active incomplete.'
    models=json.loads(subprocess.check_output([str(Path.home()/'.lmstudio/bin/lms'),'ps','--json'],cwd=Path.home()/'.lmstudio',text=True));assert len(models)==1 and models[0]['status']=='idle'
    evidence=['verification/'+n for n in names]
    for name in ['setup-status.json','current-runtime-state.json','everyday-inference.json','requirements-audit.json']:
        p=ROOT/'verification'/name;x=read(p)
        if name=='setup-status.json':x.update(updated_at_utc=now,game_work=game+' '+observed,frontend=frontend,pending=next_work)
        elif name=='current-runtime-state.json':x.update(recorded_at=now,models=models,model_state_refreshed_at=now,decomp_progress=game+' '+observed,local_inference_jobs='All known jobs terminal. Two local drafts completed; numerical and poll errors rejected by coordinator. Usual27Bidle.',emulator_jobs='No new emulator execution required. Additional nested text CPU records selected from retained verified9000frame replay.',visible_chat=frontend,MCP_updated_evidence='21components and connected CPU pipeline, exact empty-textD0 and unequalack examples. NativeChat refresh remains unverified.')
        elif name=='everyday-inference.json':x.update(updated_at=now,model=models,model_state_refreshed_at=now,frontend=frontend,latest_game_pipeline_review=str(ROOT/evidence[3]),latest_local_game_roles=str(ROOT/evidence[4]))
        else:
            x.update(recorded_at_utc=now,previous_goal_turn_classification=x['this_goal_turn_classification'],this_goal_turn_classification='progress: fourCPU helpers checked2260cases/37guards, linked pipeline54cases/13guards,9original-game intervals/5812wordwrites match; localreviewnumeric/pollerrors rejected,compact evidence examples added',next_safe_work=next_work)
            for item in x['requirements']:
                if 'decompilation test'in item['requirement']:item['state']=game+' '+observed;item['evidence']=list(dict.fromkeys(item['evidence']+evidence))
                elif 'Multiagent game'in item['requirement']:item['state']+=' New pipeline reviewer reversed BEQpoll termination and emptytextnumericresult. Contracts rejected against actual CPU fixtures; compacttool returns checked examples.';item['evidence']=list(dict.fromkeys(item['evidence']+[evidence[4]]))
                elif 'Configure LM frontend'in item['requirement']:item['state']=frontend
            x['post_review_evidence'].update({Path(e).name:str(ROOT/e)for e in evidence})
        save(p,x)
    config=read(ROOT/'config.json');config['chat_frontend']['game']['status']=game+' '+observed+' '+frontend;save(ROOT/'config.json',config)
    intake=read(ROOT/'corpus/game/project-intake.json');intake.update(latest_checked_at=now,latest_checked_status=game+' '+observed,latest_pipeline_CPU_check=str(ROOT/evidence[2]),latest_pipeline_runtime_review=str(ROOT/evidence[3]));save(ROOT/'corpus/game/project-intake.json',intake)
    p=ROOT/'projects/black-ice-white-noise/restoration/READ ME.txt';p.write_text(p.read_text()+'\nCONNECTED TEXT / SPRITE CPU PIPELINE — '+now+'\n'+game+'\n'+observed+'\nNew biwn_text.c/.h; biwn_gpu_commands adds E2B8submit4B00. biwn_inventory_pipeline.c/.h connects existing inventory routine to reconstructed CPU helpers. Reproduce: check_biwn_text.py, check_biwn_sprite.py, check_biwn_inventory_pipeline.py. Older GPU528/13regression rerun passed after module extension. Read budget/hosterrors are addedguards; partial effects remain. Formatter scratch/private moneystring implementation and devicepixels remain outside equivalence.\n')
    export=Path(read(s/'drawing-volatile-summary.json')['directory'])/'export'
    (ROOT/'CURRENT DECOMPILATION.txt').write_text('BLACK ICE WHITE NOISE — CURRENT RECONSTRUCTION\n\nComplete rebuilt game: unfinished. Original game observed in an assisted emulator.\n\nCHECKED C\n'+game+'\n'+observed+'\n\nSources:\n'+str(ROOT/'projects/black-ice-white-noise/restoration')+'\nConnected CPU checks:\n'+str(ROOT/evidence[2])+'\nOriginal-game write review:\n'+str(ROOT/evidence[3])+'\n\nAPPROXIMATE CPU EXPORT\n18,306 decoded instructions and 206 entry candidates. Automatic C remains approximate.\n'+str(export/'decompiled.c')+'\n'+str(export/'listing.asm')+'\n\nLOCAL OUTPUT TEST\nAnalyst and reviewer made numeric/poll mistakes; coordinator rejected drafts. All exact prompts/responses and corrections: POST REVIEW.txt. NativeChat remains unverified while locked.\n')
    p=ROOT/'START HERE.txt';p.write_text(p.read_text().replace('Game: 17 isolated portable C components checked;','Game: 21 isolated portable C components checked;')+'\nLatest connected pipeline: CPU text/sprite helpers now reconstructed and linked.54combined cases pass; nine original-game calls match5,812drawing/text writes. GPUprocessing and pixelrasterization still unfinished. Compactinventory evidence contains exact CPUexamples rather than model guesses.\n')
    p=ROOT/'POST REVIEW.txt';p.write_text(p.read_text()+'\nCONNECTED CPU TEXT / SPRITE / INVENTORY PIPELINE — '+now+'\n'+game+'\n'+observed+'\nWHO DID WHAT: Codex translated original14776alignment,147A6format3text,149AEtext andE2B8sprite submit. Codex compiled and checked2260standaloneCPUcases/37guards, reran528olderGPUcases/13guards, and checked54combinedCPUcases/13guards with originalhelpers executing. Codex compared additional3112nestedtextwrites in retained original-game trace. Actual resident27Banalyst12.65seconds/reviewer18.02seconds; reviewer reversedBEQpoll termination and emptytextreturn, and exceeded160wordlimit. Codex rejected drafts and extracted actualfixture examples000B0000emptytext and FFFFFFFFunequalack. No Codexsubagents,weighttraining,corepatches or GPU/rasterizer reconstruction.\nExact agent prompts/responses:\n'+str(Path(local['directory'])/'prompts-and-responses.txt')+'\nLocal audit:\n'+str(ROOT/evidence[4])+'\nCPUfixtures:\n'+text['directory']+'\n'+sprite['directory']+'\n'+pipeline['directory']+'\nOriginal-game nestedwrite review:\n'+str(ROOT/evidence[3])+'\n'+next_work+'\n')
    install=subprocess.run([str(ROOT/'.venv/bin/python'),str(ROOT/'scripts/install_frontend_config.py')],check=True,capture_output=True,text=True);(ROOT/'verification/pipeline-frontend-install.txt').write_text(install.stdout+'\n'+install.stderr)
    assert (ROOT/'presets/Game Assistant.preset.json').read_bytes()==(Path.home()/'.lmstudio/config-presets/Game Assistant.preset.json').read_bytes()
    save(ROOT/'verification/inventory-pipeline-checkpoint.json',{'recorded_at':now,'backup':read(ROOT/'verification/pipeline-checkpoint-backup.json')['directory'],'models':models,'CPU_components':21,'CPU_helper_cases':2260,'CPU_pipeline_cases':54,'runtime_word_records':5812,'full_goal_status':'active incomplete','known_compute_jobs':'terminal','evidence':evidence,'fresh_evidence_and_GameAssistant_preset_installed':True,'native_Chat_adoption':'unverified while locked','next_work':next_work})
    print(json.dumps({'components':21,'helperCPUcases':2260,'pipelineCPUcases':54,'runtime_word_records':5812,'installed':True}),flush=True)

if __name__=='__main__':main()
